'use strict';
/**
 * An appointment was booked for 00:00-01:00 at a studio that works 10:00-13:00.
 *
 * How it happened, from the owner's transcript: the customer asked for 11:00,
 * the slot was taken, and the bot offered him alternatives. Those alternatives
 * were generated by walking from 00:00 in half-hour steps, so midnight was on
 * the list. He accepted it, the calendar was asked whether midnight was free -
 * and midnight is always free - and the request was written down.
 *
 * Nothing in the system knew when the studio was open. The hours per
 * professional are free text the owner types, which is useful to read and
 * impossible to enforce.
 *
 * So there are now two settings and two gates: the slot check refuses times
 * outside the window and only ever offers times inside it, and the appointment
 * itself refuses to be created outside the window whatever the conversation
 * decided. The second gate is the one that holds, because the model is free
 * not to call the first.
 */
const { test, describe, beforeEach } = require('node:test');
const assert = require('node:assert');
const db = require('../src/store/db');
const { createMemoryBackend } = require('../src/store/backend-memory');
const settings = require('../src/settings');
const directory = require('../src/studio/directory');
const { createAppointments } = require('../src/appointments');
const {
  parseHhmm, withinHours, candidateTimes, readWindow, describe: describeWindow,
} = require('../src/studio/hours');

const DAY = { open: 10 * 60, close: 13 * 60, wraps: false, openText: '10:00', closeText: '13:00' };
const NIGHT = { open: 20 * 60, close: 2 * 60, wraps: true, openText: '20:00', closeText: '02:00' };

describe('reading a time', () => {
  test('a normal time', () => {
    assert.strictEqual(parseHhmm('10:00'), 600);
    assert.strictEqual(parseHhmm('00:00'), 0);
    assert.strictEqual(parseHhmm('9:30'), 570);
  });

  test('nonsense is refused rather than guessed at', () => {
    for (const bad of ['', '10', '25:00', '10:70', 'morgens', null, undefined, '1000']) {
      assert.strictEqual(parseHhmm(bad), null, `${JSON.stringify(bad)} must not parse`);
    }
  });
});

describe('does the appointment fit in the day', () => {
  test('midnight does not, and that is the whole bug', () => {
    assert.strictEqual(withinHours('00:00', 60, DAY), false);
  });

  test('a time inside the window does', () => {
    assert.strictEqual(withinHours('10:00', 60, DAY), true);
    assert.strictEqual(withinHours('12:00', 60, DAY), true);
  });

  test('it has to FINISH inside, not just start', () => {
    // A 90-minute massage starting at 12:00 ends half an hour after closing.
    assert.strictEqual(withinHours('12:00', 90, DAY), false);
    assert.strictEqual(withinHours('12:30', 30, DAY), true);
  });

  test('before opening is out, however close', () => {
    assert.strictEqual(withinHours('09:59', 60, DAY), false);
  });

  test('a studio that works nights is not refused its own hours', () => {
    // 20:00-02:00. This is why the window may cross midnight, and why the fix
    // could not simply be "refuse anything before 06:00".
    assert.strictEqual(withinHours('21:00', 60, NIGHT), true);
    assert.strictEqual(withinHours('00:30', 60, NIGHT), true);
    assert.strictEqual(withinHours('01:30', 60, NIGHT), false, 'ends after closing');
    assert.strictEqual(withinHours('19:00', 60, NIGHT), false, 'before opening');
    assert.strictEqual(withinHours('12:00', 60, NIGHT), false, 'the middle of the day is closed');
  });

  test('with nothing configured nothing is refused', () => {
    // A studio whose settings were typed wrong must not go off the air.
    assert.strictEqual(withinHours('00:00', 60, null), true);
  });
});

describe('the times the bot is allowed to offer', () => {
  test('never one outside the window', () => {
    for (const time of candidateTimes(DAY, { durationMin: 60 })) {
      assert.ok(withinHours(time, 60, DAY), `${time} was offered but is outside the hours`);
    }
  });

  test('never midnight - the time it actually offered', () => {
    assert.ok(!candidateTimes(DAY, { durationMin: 60 }).includes('00:00'));
  });

  test('the last one leaves room for the appointment', () => {
    const times = candidateTimes(DAY, { durationMin: 60 });
    assert.strictEqual(times[0], '10:00');
    assert.strictEqual(times[times.length - 1], '12:00', 'a 60-minute slot cannot start at 12:30');
  });

  test('a longer service gets a shorter list', () => {
    assert.deepStrictEqual(candidateTimes(DAY, { durationMin: 180 }), ['10:00']);
    assert.deepStrictEqual(candidateTimes(DAY, { durationMin: 240 }), []);
  });

  test('a night window runs through midnight in order', () => {
    const times = candidateTimes(NIGHT, { durationMin: 60 });
    assert.strictEqual(times[0], '20:00');
    assert.ok(times.includes('00:00'), 'midnight IS a slot for a studio that works nights');
    assert.strictEqual(times[times.length - 1], '01:00');
  });

  test('with nothing configured it still does not start at midnight', () => {
    assert.strictEqual(candidateTimes(null, { durationMin: 60 })[0], '08:00');
  });
});

describe('the appointment itself refuses to be created outside the hours', () => {
  let appointments;
  let professional;
  let service;

  beforeEach(async () => {
    await db.init(createMemoryBackend());
    settings.load();
    await settings.update({ studioOpenTime: '10:00', studioCloseTime: '13:00' });

    professional = (await directory.createProfessional({ name: 'Sofia' })).professional;
    service = (await directory.createService({
      name: 'Massage 60', professionalId: professional.id, durationMin: 60, priceChf: 200,
    })).service;

    appointments = createAppointments({ calendar: null, notify: null, business: 'studio' });
  });

  const request = (startTime) => appointments.create({
    chatId: '41790000000@s.whatsapp.net',
    customer_name: 'Abdul',
    professional_id: professional.id,
    service_id: service.id,
    date: '2026-12-01',
    start_time: startTime,
  });

  test('00:00 is refused, and nothing is written down', async () => {
    const res = await request('00:00');
    assert.strictEqual(res.ok, false);
    assert.match(res.error, /Oeffnungszeiten/);
    assert.strictEqual(db.all('appointments').length, 0, 'the midnight appointment must not exist');
  });

  test('the refusal tells the model what to do instead', async () => {
    const res = await request('00:00');
    assert.match(res.error, /10:00-13:00/, 'it has to say the hours');
    assert.match(res.error, /NICHT an/, 'and that it must not create the request');
  });

  test('a time inside the hours goes through', async () => {
    const res = await request('11:00');
    assert.strictEqual(res.ok, true);
    assert.strictEqual(db.all('appointments').length, 1);
    assert.strictEqual(db.all('appointments')[0].startTime, '11:00');
  });

  test('a time that would run past closing is refused', async () => {
    const res = await request('12:30'); // 60 minutes, closes 13:00
    assert.strictEqual(res.ok, false);
    assert.strictEqual(db.all('appointments').length, 0);
  });

  test('settings typed wrong do not take the studio off the air', async () => {
    await settings.update({ studioOpenTime: 'morgens', studioCloseTime: '' });
    assert.strictEqual(readWindow(settings), null);
    assert.strictEqual(describeWindow(readWindow(settings)), '');
    const res = await request('11:00');
    assert.strictEqual(res.ok, true, 'a broken setting must not refuse every appointment');
  });
});

describe('the Studio hears about a request taken on her own number', () => {
  let professional;
  let service;
  let studioHeard;
  let studioNotify;

  beforeEach(async () => {
    await db.init(createMemoryBackend());
    settings.load();
    await settings.update({ studioOpenTime: '10:00', studioCloseTime: '22:00' });

    professional = (await directory.createProfessional({ name: 'Sofia' })).professional;
    service = (await directory.createService({
      name: 'Massage 60', professionalId: professional.id, durationMin: 60, priceChf: 200,
    })).service;

    studioHeard = [];
    studioNotify = { owner: async (text, meta) => { studioHeard.push({ text, meta }); return { ok: true }; } };
  });

  const bookOn = (business) => createAppointments({
    calendar: null,
    notify: {
      appointmentRequest: async () => ({ ok: true }),
      // Without a calendar every request also tells the owner the calendar
      // entry could not be written; that is not what these tests are about.
      owner: async () => ({ ok: true }),
      toNumber: async () => ({ ok: true }),
      recipients: () => [],
    },
    business,
    studioNotify,
  }).create({
    chatId: '41790000000@s.whatsapp.net',
    customer_name: 'Abdul',
    professional_id: professional.id,
    service_id: service.id,
    date: '2026-12-01',
    start_time: '11:00',
  });

  test('a request on her line is reported to the Studio', async () => {
    await bookOn('pro-sofia');
    assert.strictEqual(studioHeard.length, 1, 'the studio was blind to this before');
    assert.match(studioHeard[0].text, /Abdul/);
    assert.match(studioHeard[0].text, /Sofia/);
    assert.match(studioHeard[0].text, /11:00/);
    assert.strictEqual(studioHeard[0].meta.line, 'pro-sofia');
  });

  test('it asks the Studio for nothing - she confirms it herself', async () => {
    await bookOn('pro-sofia');
    assert.ok(!/J zum Bestaetigen|Reply Y/i.test(studioHeard[0].text));
  });

  test('a request on the Studio\'s own number is not reported to itself twice', async () => {
    await bookOn('studio');
    assert.strictEqual(studioHeard.length, 0);
  });
});
